head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vScrenTpCD = "";
// 세션정보를 얻기위한 함수사용
scwin.Isur_cd = "", scwin.Isur_nm = "", scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.fr_bz_procs_no = "", scwin.haltTpCd = "";
scwin.getPar, scwin.setPar;
scwin.trsIdx;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const fnc = $c.frame.path("../").scwin.getPar; // Provider화면에서 fn_GetPar명칭으로 선언된 함수를 획득
        const arrPar = new Array();
        if (fnc !== undefined) {
            fnc(arrPar); // Provider화면의 callback함수를 호출하여 필요한 인수를 넘겨받는다.
            scwin.Isur_cd = (arrPar.length >= 1 ? arrPar[0] : ""); // 발행기관코드
            scwin.Isur_nm = (arrPar.length >= 2 ? arrPar[1] : ""); // 발행기관명
            scwin.Secugrp_id = (arrPar.length >= 3 ? arrPar[2] : ""); // 증권그룹ID
            scwin.Mkt_id = (arrPar.length >= 4 ? arrPar[3] : ""); // 시장구분코드
            scwin.fr_bz_procs_no = (arrPar.length >= 5 ? arrPar[4] : ""); // 업무처리번호(수정시만 유효)
            scwin.haltTpCd = (arrPar.length >= 6 ? arrPar[5] : ""); // 결산기분배기준일구분코드 1 : 결산기, 2 : 분배기준일

        }

        // alert( "Isur_cd =  " +Isur_cd + "\n"  + " Isur_nm = " + Isur_nm + "\n" + "  Secugrp_id = " + Secugrp_id + "\n" +
        //         "Mkt_id =  " +Mkt_id + "\n" + " fr_bz_procs_no = " + fr_bz_procs_no+ "\n"  );

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성
        buttonSet.setDrftInfo(btn_Drft, scwin.drft); // 기안

        if (scwin.fr_bz_procs_no !== "") {
            // Provider화면 에서 넘겨받은 업무처리번호가 ""가 아니라면 신규작성으로 간주한다.
            await scwin.search();
        } else {
            await scwin.newOnload(); // 신규작성시 호출

        }
        dts_Mst.setCellData(dts_Mst.getRowPosition(), "ISUR_CD", scwin.Isur_cd);
        dts_Mst.setCellData(dts_Mst.getRowPosition(), "ISUR_NM", scwin.Isur_nm);
        $c.cm.PanelToGroupBox(panel_3);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05621.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_OnFail
 * @description On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_OnFail = function() {
    try {
        $c.lc.fn_alertMsg('F');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05621.trs_OnFail" });
    }
};

/**
 * @method
 * @name trs_OnSuccess
 * @description On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        if (buttonSet.status === "D") {
            // 삭제처리의 응답인 경우
            await $c.win.closePopup();
        } else {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05621.trs_OnSuccess" });
    }
};

/**
 * @method
 * @name dts_Mst_OnLoadCompleted
 * @description dts_Mst 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.fr_bz_procs_no === "") {
            dts_Mst.insertRow();
        }

        // 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
        if (scwin.fr_bz_procs_no === "") {
            buttonSet.setInsertStatus();
        } else {
            $c.stf.setButtonSetWithDate(edt_MKTACT_ENFORCE_DD, false);
        }

        // alert(" dts_TrdSsp OnLoadCompleted \n" + dts_TrdSsp.Text  + "\n\n" + fn_logDSet(dts_TrdSsp) );
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05621.dts_Mst_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_DtlBf_OnLoadCompleted
 * @description dts_DtlBf 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_DtlBf_OnLoadCompleted = function(rowcount) {
    //    alert(dts_DtlBf.Text);

};

/**
 * @method
 * @name dts_DtlAf_OnLoadCompleted
 * @description dts_DtlAf 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_DtlAf_OnLoadCompleted = function(rowcount) {
    try {
        // 변경후는 항상 12개 row를 생성해줌
        dts_DtlAf.setBroadcast(false);
        for (let i = dts_DtlAf.getRowCount(); i < 13; i++) {
            dts_DtlAf.insertRow();
        }
        dts_DtlAf.setBroadcast(true, true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05621.dts_DtlAf_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_MKTACT_ENFORCE_DD_onclick
 * @description img_MKTACT_ENFORCE_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_MKTACT_ENFORCE_DD_onclick = function() {
    try {
        popUpCalendar2(edt_MKTACT_ENFORCE_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05621.img_MKTACT_ENFORCE_DD_onclick" });
    }
};

/**
 * @method
 * @name img_CHG_DD_onclick
 * @description img_CHG_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_CHG_DD_onclick = function() {
    try {
        popUpCalendar2(edt_CHG_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05621.img_CHG_DD_onclick" });
    }
};

/**
 * @method
 * @name grd_DIST_PAY_AF_onexit
 * @description grd_DIST_PAY_AF onexit 이벤트
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @param {*} olddata olddata
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_DIST_PAY_AF_onexit = async function(row, colid, olddata) {
    try {
        // alert('MxGrid_1.OnExit('+row+','+ colid+','+ olddata+')');
        if (colid === "BAS_MM" && Number(dts_DtlAf.getCellData(row, "BAS_MM")) > 12) {
            await $c.win.alert("입력월을 확인하세요.");
            dts_DtlAf.setCellData(row, "BAS_MM", "");
        } else if (colid === "BAS_DD" && Number(dts_DtlAf.getCellData(row, "BAS_DD")) > 31) {
            await $c.win.alert("입력일을 확인하세요.");
            dts_DtlAf.setCellData(row, "BAS_DD", "");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05621.grd_DIST_PAY_AF_onexit" });
    }
};

/**
 * @method
 * @name img_ChgStatDd_onclick
 * @description img_ChgStatDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ChgStatDd_onclick = function() {
    try {
        popUpCalendar2(edt_ChgStatDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05621.img_ChgStatDd_onclick" });
    }
};

/**
 * @method
 * @name img_ChgEndDd_onclick
 * @description img_ChgEndDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ChgEndDd_onclick = function() {
    try {
        popUpCalendar2(edt_ChgEndDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05621.img_ChgEndDd_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05621.btn_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description insert, update 구분
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if (scwin.fr_bz_procs_no !== "") {
        url += "?SCREN_ID=" + "ULDSTF05621.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=searchFiscalYearChange&DIV_IDX=" + DIV_IDX_FSC_MST + "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
        const sbmOptions = {
            id : "sbm_dts_Mst",
            action : "/fiscalYearChange.do",
            ref : "",
            target : "dts_Mst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        url += "?SCREN_ID=" + "ULDSTF05621.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=searchFiscalYearChange&DIV_IDX=" + DIV_IDX_DTL_DIST_BF + "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
        const sbmOptions2 = {
            id : "sbm_dts_DtlBf",
            action : "/fiscalYearChange.do",
            ref : "",
            target : "dts_DtlBf=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        url += "?SCREN_ID=" + "ULDSTF05621.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=searchFiscalYearChange&DIV_IDX=" + DIV_IDX_DTL_DIST_AF + "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
        const sbmOptions3 = {
            id : "sbm_dts_DtlAf",
            action : "/fiscalYearChange.do",
            ref : "",
            target : "dts_DtlAf=body.content",
            isProcessMsg : false
        };

        const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
        // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
 * @method
 * @name newOnload
 * @description new Onload 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.newOnload = async function() {
    const sbmOptions = {
        id : "sbm_dts_Mst",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Mst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_DtlAf",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_DtlAf=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    /* useupdate를 false로 지정함. */
    url += "?SCREN_ID=" + "ULDSTF05621.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchFiscalYearChange&DIV_IDX=" + DIV_IDX_DTL_DIST_BF + "&TRS_IDX=" + TRS_IDX_NEWSEL2 + "&ISUR_CD=" + scwin.Isur_cd;
    const sbmOptions3 = {
        id : "sbm_dts_DtlBf",
        action : "/fiscalYearChange.do",
        ref : "",
        target : "dts_DtlBf=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name saveTrs
 * @description save Trs 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveTrs = async function() {
    if (scwin.trsIdx === '1') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.trsIdx === '2') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.trsIdx === '3') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }

    // 시장조치시행일가 변경일자가 다름.
    // dts_Mst.NameString(dts_Mst.RowPosition, "CHG_DD") = dts_Mst.NameString(dts_Mst.RowPosition, "MKTACT_ENFORCE_DD");

    dts_DtlAf.setBroadcast(false);
    for (i = 1; i <= dts_DtlAf.getRowCount(); i++) {
        if (dts_DtlAf.getCellData(i, "BAS_MMDD") === "") {
            dts_DtlAf.removeRow(i);
            i--; // 삭제한 경우는 해당하는 위치에서 한번더 검색하게 함.

        }
    }
    dts_DtlAf.setBroadcast(true, true);

    // 매매거래정지 사유는 매번 업무처리 번호를 세팅함
    // 사유별 추가,삭제가 있을수 있기때문
    dts_DtlBf.setBroadcast(false);
    for (let i = 1; i <= dts_DtlBf.getRowCount(); i++) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        //
        // ********************************************************************

        dts_DtlBf.setCellData(i, "BZ_PROCS_NO", /*ORG SRC: dts_DtlBf.setNameString(i, "BZ_PROCS_NO", dts_DtlBf.NameString(i, "BZ_PROCS_NO") = );*/ X = X);
        dts_DtlBf.setCellData(i, "BYBZPROCS_SEQ", (i + 0));
        dts_DtlBf.setCellData(i, "ISUR_CD", /*ORG SRC: dts_DtlBf.setNameString(i, "ISUR_CD", dts_DtlBf.NameString(i, "ISUR_CD") = );*/ X = X);
        dts_DtlBf.setCellData(i, "CHG_BFAF_TP_CD", "1"); // 변경전후구분코드 , 1:변경전 , 2:변경후

    }
    dts_DtlBf.setBroadcast(true, true);
    dts_DtlAf.setBroadcast(false);
    for (let i = 1; i <= dts_DtlAf.getRowCount(); i++) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        //
        // ********************************************************************

        dts_DtlAf.setCellData(i, "BZ_PROCS_NO", /*ORG SRC: dts_DtlAf.setNameString(i, "BZ_PROCS_NO", dts_DtlAf.NameString(i, "BZ_PROCS_NO") = );*/ X = X);
        dts_DtlAf.setCellData(i, "BYBZPROCS_SEQ", (i + 12));
        dts_DtlAf.setCellData(i, "ISUR_CD", /*ORG SRC: dts_DtlAf.setNameString(i, "ISUR_CD", dts_DtlAf.NameString(i, "ISUR_CD") = );*/ X = X);
        dts_DtlAf.setCellData(i, "CHG_BFAF_TP_CD", "2"); // 변경전후구분코드 , 1:변경전 , 2:변경후

    }
    dts_DtlAf.setBroadcast(true, true);

    // alert(dts_DtlBf.Text );
    // alert(dts_DtlAf.Text );
    trs.KeyName = "toinb_dataid4";
    // [전환검토] trs.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : scwin.trsIdx,
    //     BZ_PROCS_NO : scwin.fr_bz_procs_no,
    //     COUNT : "3",
    //     LIST_BZ_TP_CD : LIST_BZ_TP_CD_232 + ",DIV_IDX[0]=" + DIV_IDX_FSC_MST + ",DIV_IDX[1]=" + DIV_IDX_DTL_DIST_AF + ",DIV_IDX[2]=" + DIV_IDX_DTL_DIST_BF
    // };
    const sbmOptions = {
        id : "sbm_trs",
        action : "/fiscalYearChange.do",
        ref : "dts_Mst,dts_DtlAf,dts_DtlBf",
        target : "trs=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    for (i = 1; i <= dts_DtlAf.getRowCount(); i++) {
        dts_DtlAf.setCellData(i, "BAS_MMDD", dts_DtlAf.getCellData(i, "BAS_MM") + dts_DtlAf.getCellData(i, "BAS_DD"));
        if (dts_DtlAf.getCellData(i, "BAS_MMDD") !== "" && dts_DtlAf.getCellData(i, "BAS_MMDD").length !== 4) {
            await $c.win.alert("입력한 항목중 [변경후(월,일)]을 정확히 입력해주세요. \n\n예 : 5월1일 -> 0501 ");
            return false;
        }
    }
    if (edt_CHG_DD.text.length !== 8) {
        await $c.win.alert("[변경일]을 정확히 입력하세요.");
        edt_CHG_DD.focus();
        return false;
    }
    if (!$c.lc.checkDdTm("DD", edt_MKTACT_ENFORCE_DD, "시장조치시행", false)) return false;
    if (cmb_FISCYY_CHG_RSN_CD.BindColVal === "") {
        await $c.win.alert("[변경사유]를  선택해주세요");
        cmb_FISCYY_CHG_RSN_CD.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txa_REMK, 2000, "기타")) return false;
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess('I')) return;
        if (!$c.lc.fn_mst_check(dts_Mst_Check, "2")) return;
        scwin.fr_bz_procs_no = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
        if (scwin.fr_bz_procs_no.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            scwin.trsIdx = TRS_IDX_INSERT;
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "BZ_PROCS_NO", scwin.fr_bz_procs_no);
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "ISUR_CD", scwin.Isur_cd);
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "FISCYY_DISTR_BASDD_TP_CD", "2"); // 1:결산기 , 2:수입분배기준일

            await scwin.saveTrs();
        }
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    if (await scwin.checkForm()) {
        scwin.trsIdx = TRS_IDX_UPDATE;
        if ($c.cp.isModified(dts_Mst) || $c.cp.isModified(dts_DtlAf)) {
            if (!$c.lc.fn_isProcess('U')) return;
            await scwin.saveTrs();
        } else {
            $c.lc.fn_alertNoUpdate();
        }
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    await scwin.saveTrs();
};

/**
 * @method
 * @name dscl
 * @description dscl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    let OldGet = scwin.getPar;
    const OldSet = scwin.setPar;
    scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        arr[0] = "68212C";
        arr[1] = scwin.fr_bz_procs_no;
        arr[2] = scwin.Isur_cd;
        arr[3] = '1';

        // CopyDataSet( dts_Isu , param_dts_isu);
        $c.stf.copyDataSet(dts_Mst, param_dts_mst);
        $c.stf.copyDataSet(dts_DtlBf, param_dts2);
        $c.stf.copyDataSet(dts_DtlAf, param_dts3);
        for (let i = 1; i <= param_dts3.getRowCount(); i++) {
            if ((param_dts3.getCellData(i, "BAS_MM") === "") && (param_dts3.getCellData(i, "BAS_DD") === "")) {
                param_dts3.DeleteRow(i);
                i--;
            }
        }
        return arr.length;
    };
    scwin.setPar = function(arr) {

    };
    const wth = 730 + 5;
    const hgt = 785 + 30;
    const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    const options = {
        id: "ULDSTF92024",
        title: "공시안내문작성",
        type: "browserPopup",
        width: wth,
        height: hgt,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
    scwin.getPar = OldGet;
    scwin.setPar = OldSet;
};

/**
 * @method
 * @name drft
