 */
scwin.drft = function() {
    let OldGet = scwin.getPar;
    scwin.getPar = function(arr) {
        arr[0] = scwin.fr_bz_procs_no;
        return arr.length;
    };
    $c.lc.fn_PopFindDraft();
    scwin.getPar = OldGet;
};

